"""Grammar, loosest first:
  sum     := product (('+' | '-') product)*         left associative
  product := unary (('*' | '/' | '%') unary)*       left associative; '/' is floor division, '%' Python modulo
  unary   := '-' unary | power                       so -2^2 == -(2^2)
  power   := atom ('^' unary)?                       right associative: 2^3^2 == 2^(3^2)
  atom    := integer | '(' sum ')'
"""


class Parser:
    def __init__(self, tokens):
        self.tokens, self.i = tokens, 0

    def peek(self):
        return self.tokens[self.i] if self.i < len(self.tokens) else None

    def take(self):
        self.i += 1
        return self.tokens[self.i - 1]

    def sum(self):
        value = self.product()
        while self.peek() in ('+', '-'):
            value = value + self.sum() if self.take() == '+' else value - self.sum()
        return value

    def product(self):
        value = self.unary()
        while self.peek() in ('*', '/', '%'):
            op, right = self.take(), self.unary()
            value = value * right if op == '*' else value // right if op == '/' else value % right
        return value

    def unary(self):
        if self.peek() == '-':
            self.take()
            return -self.unary()
        return self.power()

    def power(self):
        base = self.atom()
        if self.peek() == '^':
            self.take()
            return base ** self.unary()
        return base

    def atom(self):
        token = self.take()
        if token == '(':
            value = self.sum()
            if self.take() != ')':
                raise SyntaxError('expected )')
            return value
        if isinstance(token, int):
            return token
        raise SyntaxError(repr(token))

